<main class="container py-4 py-md-5"><div class="row justify-content-center"><div class="col-12 col-md-7 col-lg-5"><section class="card shadow-sm border-0 p-4"><h1 class="h3 text-center mb-4">Réinitialiser le mot de passe</h1><?php if (!empty($success)): ?><div class="alert alert-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><?php if (!empty($error)): ?><div class="alert alert-danger"><?= htmlspecialchars($error) ?></div><?php endif; ?><form action="index.php?page=reinitialiser_mot_de_passe" method="post"><?php if (!empty($token)): ?><input type="hidden" name="token" value="<?= htmlspecialchars($token) ?>"><label for="mdp" class="form-label">Nouveau mot de passe</label><input id="mdp" type="password" class="form-control mb-2" name="mdp" minlength="10" pattern="(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])(?=.*[^A-Za-z0-9]).{10,}" required><p class="form-text">10 caractères minimum avec majuscule, minuscule, chiffre et caractère spécial.</p><button class="btn btn-primary w-100">Définir mon mot de passe</button><?php else: ?><label for="email" class="form-label">Adresse e-mail</label><input id="email" type="email" class="form-control mb-3" name="email" autocomplete="email" required><button class="btn btn-primary w-100">Envoyer le lien</button><?php endif; ?></form><p class="text-center mt-3 mb-0"><a href="?page=connexion">Retour à la connexion</a></p></section></div></div></main>
